%% Local functions
function [topas_dims, resolution_mm, dicomCropInfo] = getCurrentTopasGrid(project_dir)
dicom_info_file = fullfile(project_dir, 'dicom', 'dicomCropInfo.mat');
if ~isfile(dicom_info_file)
    error('Missing DICOM crop info: %s. Run crop_dicom_for_topas first.', dicom_info_file);
end

s = load(dicom_info_file, 'dicomCropInfo');
dicomCropInfo = s.dicomCropInfo;

required_fields = {'outputColumnsRowsSlices', 'pixelSpacingRowColMm', 'sliceSpacingMm'};
for f = 1:numel(required_fields)
    if ~isfield(dicomCropInfo, required_fields{f})
        error('dicomCropInfo.%s is missing in %s.', required_fields{f}, dicom_info_file);
    end
end

topas_dims = double(dicomCropInfo.outputColumnsRowsSlices(:).');
resolution_mm = [ ...
    double(dicomCropInfo.pixelSpacingRowColMm(2)), ...
    double(dicomCropInfo.pixelSpacingRowColMm(1)), ...
    double(dicomCropInfo.sliceSpacingMm)];

if numel(topas_dims) ~= 3 || any(~isfinite(topas_dims)) || any(topas_dims <= 0) || any(topas_dims ~= round(topas_dims))
    error('Invalid TOPAS dimensions in dicomCropInfo: %s.', mat2str(topas_dims));
end
if any(~isfinite(resolution_mm)) || any(resolution_mm <= 0)
    error('Invalid TOPAS resolution in dicomCropInfo: %s.', mat2str(resolution_mm));
end
end

function tf = defaultUseParallel()
% Current 0.5 x 0.5 x 2 mm scorer files are large; serial import is safer.
tf = false;
end

function spot_groups = readTopasSpotGroupsFromSpotsFiles(spots_dir, ion_label)
if ~isfolder(spots_dir)
    error('Missing TOPAS scripts folder: %s.', spots_dir);
end

files = dir(fullfile(spots_dir, sprintf('spots_%s_*.txt', ion_label)));
if isempty(files)
    error('No spots_%s_*.txt files found in %s.', ion_label, spots_dir);
end

chunk_ids = nan(numel(files), 1);
for i = 1:numel(files)
    token = regexp(files(i).name, sprintf('^spots_%s_(\\d+)\\.txt$', ion_label), 'tokens', 'once');
    if isempty(token)
        continue;
    end
    chunk_ids(i) = str2double(token{1});
end

valid = isfinite(chunk_ids);
files = files(valid);
chunk_ids = chunk_ids(valid);
if isempty(files)
    error('No numbered spots_%s_XX.txt files found in %s.', ion_label, spots_dir);
end

[chunk_ids, order] = sort(chunk_ids);
files = files(order);
if ~isequal(chunk_ids(:), (1:numel(chunk_ids))')
    error('Chunk IDs for spots_%s_*.txt are not contiguous starting at 1: %s.', ...
        ion_label, mat2str(chunk_ids(:).'));
end

spot_groups = cell(numel(files), 1);
for i = 1:numel(files)
    spot_groups{i} = parseGlobalSpotIdsFromSpotsFile(fullfile(files(i).folder, files(i).name));
end
end

function spot_ids = parseGlobalSpotIdsFromSpotsFile(spots_file)
text = fileread(spots_file);
token = regexp(text, 'iv:Tf/Scatterer1/L0/Values\s*=\s*(\d+)\s+([^\r\n]+)', 'tokens', 'once');
if isempty(token)
    error('Could not find global spot ID line iv:Tf/Scatterer1/L0/Values in %s.', spots_file);
end

declared_count = str2double(token{1});
spot_ids = sscanf(token{2}, '%f').';
if numel(spot_ids) ~= declared_count
    error('Spot count mismatch in %s: declared %d IDs, parsed %d.', ...
        spots_file, declared_count, numel(spot_ids));
end
if any(~isfinite(spot_ids)) || any(spot_ids ~= round(spot_ids)) || any(spot_ids <= 0)
    error('Invalid global spot IDs in %s.', spots_file);
end
spot_ids = double(spot_ids(:));
end

function [topas_chunks, run_ids, spot_ids] = makeSpotWorkItems(topas_spot_groups)
    num_spots = sum(cellfun(@numel, topas_spot_groups));
    topas_chunks = zeros(num_spots, 1);
    run_ids = zeros(num_spots, 1);
    spot_ids = zeros(num_spots, 1);

    next_ix = 1;
    for chunk = 1:numel(topas_spot_groups)
        ids = topas_spot_groups{chunk}(:);
        n = numel(ids);
        ix = next_ix:(next_ix + n - 1);
        topas_chunks(ix) = chunk;
        run_ids(ix) = (0:(n - 1)).';
        spot_ids(ix) = ids;
        next_ix = next_ix + n;
    end
end

function [cols, sums, raw_sums, dropped_sums, kept_nnz, dropped_nnz, missing, bad] = buildSparseSpotColumns( ...
    chunk, run_id, scorer_dir, scorer_names, scorer_limits, preferred_scorer_extension, ...
    topas_to_matrad_idx, num_voxels, fail_on_missing)

    cols = {
        sparse(num_voxels, 1)
        sparse(num_voxels, 1)
        sparse(num_voxels, 1)
        sparse(num_voxels, 1)
        };
    sums = zeros(4, 1);
    raw_sums = zeros(4, 1);
    dropped_sums = zeros(4, 1);
    kept_nnz = zeros(4, 1);
    dropped_nnz = zeros(4, 1);
    missing = strings(0, 1);
    bad = strings(0, 1);

    files = cell(numel(scorer_names), 1);
    for i = 1:numel(scorer_names)
        files{i} = resolveTopasScorerFile(scorer_dir, scorer_names{i}, ...
            chunk, run_id, preferred_scorer_extension);
        if ~isfile(files{i})
            missing(end+1, 1) = string(files{i}); %#ok<AGROW>
        end
    end

    if ~isempty(missing)
        if fail_on_missing
            error('Missing required OSMK scorer file for chunk %d run %04d: %s', ...
                chunk, run_id, missing(1));
        end
        return;
    end

    for i = 1:numel(scorer_names)
        try
            [cols{i}, sums(i), raw_sums(i), dropped_sums(i), kept_nnz(i), dropped_nnz(i)] = ...
                readThresholdedSparseColumn(files{i}, topas_to_matrad_idx, ...
                    scorer_limits(i), num_voxels);
        catch ME
            if fail_on_missing
                rethrow(ME);
            end
            warning('Failed to read %s: %s', files{i}, ME.message);
            bad = string(files(:));
            cols = {
                sparse(num_voxels, 1)
                sparse(num_voxels, 1)
                sparse(num_voxels, 1)
                sparse(num_voxels, 1)
                };
            sums(:) = 0;
            raw_sums(:) = 0;
            dropped_sums(:) = 0;
            kept_nnz(:) = 0;
            dropped_nnz(:) = 0;
            return;
        end
    end
end

function filename = resolveTopasScorerFile(scorer_dir, scorer_name, chunk, run_id, preferred_ext)
    extensions = unique([{preferred_ext}, {'.bin'}, {'.csv'}], 'stable');

    for extIx = 1:numel(extensions)
        ext = extensions{extIx};
        exact_names = {
            fullfile(scorer_dir, sprintf('%s_%02d_Run_%04d%s', scorer_name, chunk, run_id, ext))
            };

        for exactIx = 1:numel(exact_names)
            if isfile(exact_names{exactIx})
                filename = exact_names{exactIx};
                return;
            end
        end

        labelled = dir(fullfile(scorer_dir, ...
            sprintf('%s_*_%02d_Run_%04d%s', scorer_name, chunk, run_id, ext)));
        if ~isempty(labelled)
            [~, order] = sort({labelled.name});
            labelled = labelled(order);
            filename = fullfile(labelled(1).folder, labelled(1).name);
            return;
        end
    end

    filename = fullfile(scorer_dir, sprintf('%s_*_%02d_Run_%04d%s', ...
        scorer_name, chunk, run_id, preferred_ext));
end

function [col_sparse, kept_sum, raw_sum, dropped_sum, kept_nnz, dropped_nnz] = readThresholdedSparseColumn( ...
    filename, topas_to_matrad_idx, value_limit, num_voxels)

    values = readTopasScorerValues(filename, num_voxels);
    finite_mask = isfinite(values);
    nonzero_mask = finite_mask & values ~= 0;
    keep_mask = nonzero_mask & abs(values) >= value_limit;

    matrad_rows = double(topas_to_matrad_idx(keep_mask));
    kept_values = values(keep_mask);
    raw_sum = sum(values(nonzero_mask));

    col_sparse = sparse(matrad_rows, ones(numel(matrad_rows), 1), ...
        kept_values, num_voxels, 1);
    kept_sum = sum(kept_values);
    dropped_sum = raw_sum - kept_sum;
    kept_nnz = numel(kept_values);
    dropped_nnz = nnz(nonzero_mask) - kept_nnz;
end

function values = readTopasScorerValues(filename, expected_rows)
    [~, ~, ext] = fileparts(filename);
    switch lower(ext)
        case '.bin'
            values = readTopasBinaryValues(filename, expected_rows);
        case '.csv'
            values = readTopasCsvValues(filename, expected_rows);
        otherwise
            error('Unsupported TOPAS scorer file extension in %s.', filename);
    end
end

function values = readTopasBinaryValues(filename, expected_rows)
    fid = fopen(filename, 'rb');
    if fid == -1
        error('Cannot open TOPAS binary file: %s', filename);
    end
    cleaner = onCleanup(@() fclose(fid));

    values = fread(fid, expected_rows, 'double=>double');
    if numel(values) ~= expected_rows
        error('Binary value count mismatch in %s: got %d, expected %d.', ...
            filename, numel(values), expected_rows);
    end
end

function values = readTopasCsvValues(filename, expected_rows)
    fid = fopen(filename, 'r');
    if fid == -1
        error('Cannot open TOPAS CSV file: %s', filename);
    end
    cleaner = onCleanup(@() fclose(fid));

    data = textscan(fid, '%*f%*f%*f%f', 'Delimiter', ',', ...
        'CommentStyle', '#');
    values = data{1};

    if isempty(values)
        error('Empty TOPAS CSV file: %s', filename);
    end
    if numel(values) ~= expected_rows
        error('Row count mismatch in %s: got %d, expected %d.', ...
            filename, numel(values), expected_rows);
    end
end

function verifyTopasScorerLayout(filename, topas_dims)
    [~, ~, ext] = fileparts(filename);
    switch lower(ext)
        case '.bin'
            verifyTopasBinaryLayout(filename, topas_dims);
        case '.csv'
            verifyTopasCsvIndexOrder(filename, topas_dims);
        otherwise
            error('Unsupported TOPAS scorer file extension in %s.', filename);
    end
end

function verifyTopasBinaryLayout(filename, topas_dims)
    expected_bytes = prod(topas_dims) * 8;
    file_info = dir(filename);
    if isempty(file_info)
        error('Cannot find TOPAS binary file for layout verification: %s', filename);
    end
    if file_info.bytes ~= expected_bytes
        error('Binary size mismatch in %s: got %d bytes, expected %d.', ...
            filename, file_info.bytes, expected_bytes);
    end

    header_file = [filename 'header'];
    if isfile(header_file)
        verifyTopasBinaryHeader(header_file, topas_dims);
    end
end

function verifyTopasBinaryHeader(header_file, topas_dims)
    text = fileread(header_file);
    axes = 'XYZ';
    for axisIx = 1:numel(axes)
        pattern = sprintf('#\\s*%s\\s+in\\s+(\\d+)\\s+bins?', axes(axisIx));
        token = regexp(text, pattern, 'tokens', 'once');
        if isempty(token)
            error('Could not parse %s-axis binning from %s.', axes(axisIx), header_file);
        end
        n_bins = str2double(token{1});
        if n_bins ~= topas_dims(axisIx)
            error('%s-axis bin mismatch in %s: got %d, expected %d.', ...
                axes(axisIx), header_file, n_bins, topas_dims(axisIx));
        end
    end
end

function verifyTopasCsvIndexOrder(filename, topas_dims)
    fid = fopen(filename, 'r');
    if fid == -1
        error('Cannot open TOPAS CSV file for index verification: %s', filename);
    end
    cleaner = onCleanup(@() fclose(fid));

    data = textscan(fid, '%f%f%f%*f', 'Delimiter', ',', ...
        'CommentStyle', '#', 'CollectOutput', true);
    raw = data{1};
    expected_rows = prod(topas_dims);

    if size(raw, 1) ~= expected_rows
        error('Row count mismatch in %s: got %d, expected %d.', ...
            filename, size(raw, 1), expected_rows);
    end

    x = raw(:, 1);
    y = raw(:, 2);
    z = raw(:, 3);
    if any(x < 0 | y < 0 | z < 0 | ...
           x >= topas_dims(1) | y >= topas_dims(2) | z >= topas_dims(3) | ...
           x ~= floor(x) | y ~= floor(y) | z ~= floor(z))
        error('Invalid TOPAS voxel indices in %s.', filename);
    end

    linear_idx = x + y .* topas_dims(1) + z .* topas_dims(1) .* topas_dims(2);
    expected_idx = (0:(expected_rows - 1))';
    if any(linear_idx ~= expected_idx)
        error(['Unexpected TOPAS CSV voxel order in %s. This sparse builder ', ...
            'expects standard TOPAS order with X changing fastest.'], filename);
    end
end

function topas_to_matrad_idx = makeTopasToMatRadIndex(topas_dims, flip_y)
    if nargin < 2
        flip_y = false;
    end

    num_voxels = prod(topas_dims);
    topas_linear = reshape(uint32(1:num_voxels), topas_dims);
    if flip_y
        topas_linear = topas_linear(:, end:-1:1, :);
    end
    topas_idx_in_matrad_order = permute(topas_linear, [2, 1, 3]);
    topas_to_matrad_idx = zeros(num_voxels, 1, 'uint32');
    topas_to_matrad_idx(topas_idx_in_matrad_order(:)) = uint32(1:num_voxels);
end

function out = flattenStringCells(cells_in)
    out = strings(0, 1);
    for i = 1:numel(cells_in)
        if ~isempty(cells_in{i})
            out = [out; string(cells_in{i}(:))]; %#ok<AGROW>
        end
    end
end
